INSERT INTO `recipe` VALUES (101, '藜麦鸡胸能量碗', '高蛋白、低负担的轻食主餐，适合减脂和塑形期。', '午餐', '轻食', 20, '简单', 1, 403.4, 403.4, 45.7, 36.8, 7.6, 5.0, '[\"藜麦煮熟备用\",\"鸡胸肉煎熟切片\",\"生菜和紫甘蓝洗净切丝\",\"将所有食材装碗后拌匀即可\"]', '可加入少量黑胡椒提升风味。', NULL, NULL, 0, 4.8, 0, 0, 0, '减脂人群、健身人群', '减肥减脂', 1, '2026-03-24 21:40:37', '2026-03-24 21:40:37');
